window.PROBABILITY_BOOK_DATA = {"chapter":5,"title":"Binomial & Poisson distributions","total":85,"range":[345,429],"questions":[{"id":345,"question":"If ‘𝑝’,‘𝑞’ and ‘𝑛’ are probability of success, failure\nand number of trials respectively in a Binomial\nDistribution, what is its Standard Deviation?","page":30,"marks":1,"answer":"√(npq)","steps":[{"title":"Given and formula","formula":"For X ~ Bin(n,p), Var(X) = np(1−p) = npq."},{"title":"Substitution and result","formula":"Take the square root: SD(X) = √(npq)."}],"shareImage":"share/q345.jpg","shareImageSize":[1358,233]},{"id":346,"question":"If ‘𝑚’ is the mean of a Poisson Distribution, then\nvariance is given by ___________.","page":30,"marks":1,"answer":"m","steps":[{"title":"Given and formula","formula":"For a Poisson variable, the mean equals its rate."},{"title":"Substitution and result","formula":"Var(X) = rate = m."}],"shareImage":"share/q346.jpg","shareImageSize":[1358,210]},{"id":347,"question":"If ‘𝜆’ is the mean of Poisson Distribution, the 𝑃(0)\nis given by ___________.","page":30,"marks":1,"answer":"e^(−λ)","steps":[{"title":"Given and formula","formula":"Use P(X = k) = e^(−λ)λ^k/k!."},{"title":"Substitution and result","formula":"Set k = 0 and use λ⁰ = 0! = 1."}],"shareImage":"share/q347.jpg","shareImageSize":[1358,202]},{"id":348,"question":"For a Poisson Distribution, if mean = 1, then 𝑃(1)\nis?","page":30,"marks":1,"answer":"P(X = 1) ≈ 0.36787944","steps":[{"title":"Given and probability formula","formula":"λ = 1.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X = 1)","formula":"P(X = 1)\n= e^(−1)(1)^1/1!\n≈ 0.36787944"}],"shareImage":"share/q348.jpg","shareImageSize":[1358,202]},{"id":349,"question":"For a Poisson variable X with P(X = 1) = (2/3)P(X = 2), find the variance.","page":30,"marks":1,"answer":"3","steps":[{"title":"Given and formula","formula":"P(X = x) = e^(−λ)λˣ/x! and Var(X) = λ."},{"title":"Substitution and result","formula":"Given P(X = 1) = (2/3)P(X = 2).\ne^(−λ)λ = (2/3)e^(−λ)λ²/2!\nDividing by e^(−λ)λ for λ > 0 gives 1 = λ/3.\n∴ λ = 3 and Var(X) = 3."}],"shareImage":"share/q349.jpg","shareImageSize":[1358,278]},{"id":350,"question":"If 𝑋 is a poisson random variate with mean 3, then\n𝑃(|𝑋 − 3| < 1) will be _____.","page":30,"marks":1,"answer":"P(|X − 3| < 1) = P(X = 3) ≈ 0.22404181","steps":[{"title":"Given and probability formula","formula":"λ = 3.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(|X − 3| < 1) = P(X = 3)","formula":"P(X = 3)\n= e^(−3)(3)^3/3!\n≈ 0.22404181"}],"shareImage":"share/q350.jpg","shareImageSize":[1358,259]},{"id":351,"question":"A lot has 10 % defective items. Ten items are\nchosen randomly from this lot. The probability that\nexactly 2 of the chosen items are defective is","page":31,"marks":1,"answer":"Exactly two defectives ≈ 0.19371024","steps":[{"title":"Given and probability formula","formula":"n = 10, p = 0.1, q = 1 − p = 0.9.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 10."},{"title":"Exactly two defectives","formula":"P(X = 2)\n= C(10,2)(0.1)^2(0.9)^8\n≈ 0.19371024"}],"shareImage":"share/q351.jpg","shareImageSize":[1358,235]},{"id":352,"question":"In a binomial distribution the mean is 15 and\nvariance is 10, then parameter 𝑛 is","page":31,"marks":1,"answer":"45","steps":[{"title":"Given and formula","formula":"np = 15 and np(1−p) = 10."},{"title":"Substitution and result","formula":"1−p = 10/15 = 2/3, so p = 1/3 and n = 15/(1/3) = 45."}],"shareImage":"share/q352.jpg","shareImageSize":[1358,202]},{"id":353,"question":"Consider an unbiased cubic dice with opposite\nfaces colored identically and each face-colored red,\nblue or green such that each color appears only two\ntimes on the dice. If the dice thrown thrice, the\nprobability of getting red color on top face of the\ndice at least twice is ______.","page":31,"marks":1,"answer":"At least two reds ≈ 0.25925926","steps":[{"title":"Given and probability formula","formula":"n = 3, p = 0.33333333, q = 1 − p = 0.66666667.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 3."},{"title":"At least two reds","formula":"P(X = 2) + P(X = 3)\n= C(3,2)(0.33333333)^2(0.66666667)^1 + C(3,3)(0.33333333)^3(0.66666667)^0\n≈ 0.25925926"}],"shareImage":"share/q353.jpg","shareImageSize":[1358,329]},{"id":354,"question":"The number of tosses of a coin that are needed so\nthat the probability of getting at least one head being\n0.875 is ______.","page":31,"marks":1,"answer":"3","steps":[{"title":"Given and formula","formula":"P(at least one head in n tosses) = 1 − (1/2)^n."},{"title":"Substitution and result","formula":"Set (1/2)^n = 1 − 0.875 = 1/8, so n = 3."}],"shareImage":"share/q354.jpg","shareImageSize":[1358,234]},{"id":355,"question":"If 20% of the bolts produced by a machine are\ndefective, the probability that out of 4 bolts chosen,\nat most 2 bolts will be defective is,","page":31,"marks":1,"answer":"At most two defectives ≈ 0.9728","steps":[{"title":"Given and probability formula","formula":"n = 4, p = 0.2, q = 1 − p = 0.8.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 4."},{"title":"At most two defectives","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= C(4,0)(0.2)^0(0.8)^4 + C(4,1)(0.2)^1(0.8)^3 + C(4,2)(0.2)^2(0.8)^2\n≈ 0.9728"}],"shareImage":"share/q355.jpg","shareImageSize":[1358,233]},{"id":356,"question":"A fair coin is tossed independently four times. The\nprobability of the event\n“the number of times heads show up is more than\nthe number of times tails show up”","page":31,"marks":1,"answer":"More heads than tails ≈ 0.3125","steps":[{"title":"Given and probability formula","formula":"n = 4, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 4."},{"title":"More heads than tails","formula":"P(X = 3) + P(X = 4)\n= C(4,3)(0.5)^3(0.5)^1 + C(4,4)(0.5)^4(0.5)^0\n≈ 0.3125"}],"shareImage":"share/q356.jpg","shareImageSize":[1358,265]},{"id":357,"question":"A fair coin is tossed 6 times. The probability of\nobtaining at least 5 heads is,","page":31,"marks":1,"answer":"At least five heads ≈ 0.109375","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"At least five heads","formula":"P(X = 5) + P(X = 6)\n= C(6,5)(0.5)^5(0.5)^1 + C(6,6)(0.5)^6(0.5)^0\n≈ 0.109375"}],"shareImage":"share/q357.jpg","shareImageSize":[1358,201]},{"id":358,"question":"A dice is thrown 6 times. If getting an odd number is\na success, the probability of 5 successes is,","page":31,"marks":1,"answer":"Exactly five odd rolls ≈ 0.09375","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"Exactly five odd rolls","formula":"P(X = 5)\n= C(6,5)(0.5)^5(0.5)^1\n≈ 0.09375"}],"shareImage":"share/q358.jpg","shareImageSize":[1358,202]},{"id":359,"question":"A dice is thrown 6 times. If getting an odd number is\na success, the probability of at least 5 successes is,","page":31,"marks":1,"answer":"At least five odd rolls ≈ 0.109375","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"At least five odd rolls","formula":"P(X = 5) + P(X = 6)\n= C(6,5)(0.5)^5(0.5)^1 + C(6,6)(0.5)^6(0.5)^0\n≈ 0.109375"}],"shareImage":"share/q359.jpg","shareImageSize":[1358,201]},{"id":360,"question":"A dice is thrown 6 times. If getting an odd number is\na success, the probability of at the most 5 successes\nis,","page":31,"marks":1,"answer":"At most five odd rolls ≈ 0.984375","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"At most five odd rolls","formula":"1 − (P(X = 6))\n= 1 − [C(6,6)(0.5)^6(0.5)^0]\n≈ 0.984375"}],"shareImage":"share/q360.jpg","shareImageSize":[1358,233]},{"id":361,"question":"If the probability of a defective bolt is 0.1. What will\nbe the mean of the distribution of defective bolts in a\ntotal of 400?","page":31,"marks":1,"answer":"40","steps":[{"title":"Given and formula","formula":"A binomial count has mean np."},{"title":"Substitution and result","formula":"400 × 0.1 = 40."}],"shareImage":"share/q361.jpg","shareImageSize":[1358,234]},{"id":362,"question":"Find the expectation for how many bacteria there\nare per field if there are 2350 bacteria are randomly\ndistributed over 340 fields (all having the same\nsize) next to each other.","page":31,"marks":1,"answer":"6.9117647","steps":[{"title":"Given and formula","formula":"Each bacterium has probability 1/340 of being in a given field."},{"title":"Substitution and result","formula":"By linearity of expectation, 2350 × (1/340) ≈ 6.912."}],"shareImage":"share/q362.jpg","shareImageSize":[1358,264]},{"id":363,"question":"A student arrives late for a class 40% of the time.\nClass meets five times each week. The probability if\nstudent being late for at least three classes in a given\nweek is,","page":31,"marks":1,"answer":"Late at least three times ≈ 0.31744","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.4, q = 1 − p = 0.6.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"Late at least three times","formula":"P(X = 3) + P(X = 4) + P(X = 5)\n= C(5,3)(0.4)^3(0.6)^2 + C(5,4)(0.4)^4(0.6)^1 + C(5,5)(0.4)^5(0.6)^0\n≈ 0.31744"}],"shareImage":"share/q363.jpg","shareImageSize":[1358,265]},{"id":364,"question":"A student arrives late for a class 40% of the time.\nClass meets five times each week. The probability of\nstudent will not be late at all during a given week is,","page":31,"marks":1,"answer":"Never late ≈ 0.07776","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.4, q = 1 − p = 0.6.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"Never late","formula":"P(X = 0)\n= C(5,0)(0.4)^0(0.6)^5\n≈ 0.07776"}],"shareImage":"share/q364.jpg","shareImageSize":[1358,234]},{"id":365,"question":"The mean and variance of a binomial variate are 8\nand 6 then parameter n is","page":31,"marks":1,"answer":"32","steps":[{"title":"Given and formula","formula":"np = 8 and np(1−p) = 6."},{"title":"Substitution and result","formula":"1−p = 6/8 = 3/4. Therefore p = 1/4 and n = 8/(1/4) = 32."}],"shareImage":"share/q365.jpg","shareImageSize":[1358,201]},{"id":366,"question":"In a company, there are 250 workers. The\nprobability of a worker remain absent on any day is\n0.02. The probability that on a day seven workers\nare absent is,","page":31,"marks":1,"answer":"Exactly seven absent ≈ 0.10444486","steps":[{"title":"Given and probability formula","formula":"λ = 5.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Exactly seven absent","formula":"P(X = 7)\n= e^(−5)(5)^7/7!\n≈ 0.10444486"}],"note":"The practice book uses the Poisson approximation with λ = 250 × 0.02. The exact binomial result is about 0.1050739.","shareImage":"share/q366.jpg","shareImageSize":[1358,265]},{"id":367,"question":"In the inspection of tin plate produced by a\ncontinuous electrolytic process, 0.2 imperfections\nspotted per minute, on average. The probability of\nspotting one imperfection in 3 minutes is,","page":31,"marks":1,"answer":"Exactly one imperfection ≈ 0.32928698","steps":[{"title":"Given and probability formula","formula":"λ = 0.6.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Exactly one imperfection","formula":"P(X = 1)\n= e^(−0.6)(0.6)^1/1!\n≈ 0.32928698"}],"shareImage":"share/q367.jpg","shareImageSize":[1358,265]},{"id":368,"question":"In the inspection of tin plate produced by a\ncontinuous electrolytic process, 0.2 imperfections\nspotted per minute, on average. The probability of\nspotting at least two imperfections in 5 minutes is,","page":31,"marks":1,"answer":"At least two imperfections ≈ 0.26424112","steps":[{"title":"Given and probability formula","formula":"λ = 1.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At least two imperfections","formula":"1 − (P(X = 0) + P(X = 1))\n= 1 − [e^(−1)(1)^0/0! + e^(−1)(1)^1/1!]\n≈ 0.26424112"}],"shareImage":"share/q368.jpg","shareImageSize":[1358,265]},{"id":369,"question":"In the inspection of tin plate produced by a\ncontinuous electrolytic process, 0.2 imperfections\nspotted per minute, on average. The probability of\nspotting at most one imperfection in 15 minutes is,","page":31,"marks":1,"answer":"At most one imperfection ≈ 0.19914827","steps":[{"title":"Given and probability formula","formula":"λ = 3.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At most one imperfection","formula":"P(X = 0) + P(X = 1)\n= e^(−3)(3)^0/0! + e^(−3)(3)^1/1!\n≈ 0.19914827"}],"shareImage":"share/q369.jpg","shareImageSize":[1358,336]},{"id":370,"question":"The number of defects in a thin copper wire follows\nPoisson distribution with mean 2.3 defects per\nmillimeter. Then the probability of exactly two\ndefects per millimeter of wire is,","page":32,"marks":1,"answer":"Exactly two defects ≈ 0.26518464","steps":[{"title":"Given and probability formula","formula":"λ = 2.3.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Exactly two defects","formula":"P(X = 2)\n= e^(−2.3)(2.3)^2/2!\n≈ 0.26518464"}],"shareImage":"share/q370.jpg","shareImageSize":[1358,265]},{"id":371,"question":"If 𝑃(1) = 𝑃(5) in Poisson distribution, then the\nvalue of mean is,","page":32,"marks":1,"answer":"3.3097509","steps":[{"title":"Given and formula","formula":"Cancel e^(−λ) in P(X = 1) = P(X = 5) with λ > 0."},{"title":"Substitution and result","formula":"λ = λ⁵/120, so λ⁴ = 120 and λ ≈ 3.3098."}],"shareImage":"share/q371.jpg","shareImageSize":[1358,203]},{"id":372,"question":"In an experiment, positive and negative values are\nequally likely to occur. The probability of obtaining\nat most one negative value in five trials is _____.","page":32,"marks":1,"answer":"At most one negative ≈ 0.1875","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"At most one negative","formula":"P(X = 0) + P(X = 1)\n= C(5,0)(0.5)^0(0.5)^5 + C(5,1)(0.5)^1(0.5)^4\n≈ 0.1875"}],"shareImage":"share/q372.jpg","shareImageSize":[1358,233]},{"id":373,"question":"If ‘16’ is the mean of a Poisson Distribution, then\nvariance is given by ___________","page":32,"marks":1,"answer":"16","steps":[{"title":"Given and formula","formula":"A Poisson variable has variance equal to its mean."},{"title":"Substitution and result","formula":"Var(X) = 16."}],"shareImage":"share/q373.jpg","shareImageSize":[1358,204]},{"id":374,"question":"A student takes an 18-question multiple choice\nexam, with four choice per question. Suppose one\nof the choices in obviously incorrect, and the\nstudent makes an “educated” guess of the\nremaining choices, then the expected number of the\ncorrect answer is","page":32,"marks":1,"answer":"6","steps":[{"title":"Given and formula","formula":"Each guess has probability 1/3 of being right after eliminating one choice."},{"title":"Substitution and result","formula":"E[X] = 18 × (1/3) = 6."}],"shareImage":"share/q374.jpg","shareImageSize":[1358,328]},{"id":375,"question":"The overall percentage of failure in an examination\nis 30. What is the probability that in a group of 5\nstudents at least 4 passed the examination?","page":32,"marks":1,"answer":"At least four passes ≈ 0.52822","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.7, q = 1 − p = 0.3.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"At least four passes","formula":"P(X = 4) + P(X = 5)\n= C(5,4)(0.7)^4(0.3)^1 + C(5,5)(0.7)^5(0.3)^0\n≈ 0.52822"}],"shareImage":"share/q375.jpg","shareImageSize":[1358,235]},{"id":376,"question":"Obtain the binomial distribution for which mean is\n10 and variance is 5.","page":32,"marks":2,"answer":"X ~ Bin(20, 0.5)","steps":[{"title":"Given and formula","formula":"np = 10 and np(1−p) = 5."},{"title":"Substitution and result","formula":"1−p = 5/10, so p = 0.5 and n = 20. P(X = k) = C(20,k)/2²⁰ for k = 0,…,20."}],"shareImage":"share/q376.jpg","shareImageSize":[760,201]},{"id":377,"question":"The mean and variance of a binomial variate are 8\nand 6. Find 𝑃(𝑋 ≥ 2).","page":32,"marks":2,"answer":"At least two successes ≈ 0.99882806","steps":[{"title":"Given and parameter calculation","formula":"Mean: np = 8   (1)\nVariance: npq = 6   (2)\nDivide (2) by (1): q = 6/8 = 3/4.\n∴ p = 1 − q = 1/4. From (1), n = 8/(1/4) = 32."},{"title":"Probability formula","formula":"n = 32, p = 0.25, q = 1 − p = 0.75.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 32."},{"title":"At least two successes","formula":"1 − (P(X = 0) + P(X = 1))\n= 1 − [C(32,0)(0.25)^0(0.75)^32 + C(32,1)(0.25)^1(0.75)^31]\n≈ 0.99882806"}],"shareImage":"share/q377.jpg","shareImageSize":[760,202]},{"id":378,"question":"The probability that a patient will be cured of\ncorona virus when injected with the new vaccine is\n0.8. Find the probability that exactly 3 out of the 8\ncorona virus patients will be cured on being\ninjected with the vaccine.","page":32,"marks":3,"answer":"Exactly three recoveries ≈ 0.00917504","steps":[{"title":"Given and probability formula","formula":"n = 8, p = 0.8, q = 1 − p = 0.2.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 8."},{"title":"Exactly three recoveries","formula":"P(X = 3)\n= C(8,3)(0.8)^3(0.2)^5\n≈ 0.00917504"}],"shareImage":"share/q378.jpg","shareImageSize":[760,297]},{"id":379,"question":"The average percentage of failure in a certain\nexamination is 40. What is the probability that out of\na group of 6 candidates, at least 4 passed in\nexamination?","page":32,"marks":3,"answer":"At least four passes ≈ 0.54432","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.6, q = 1 − p = 0.4.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"At least four passes","formula":"P(X = 4) + P(X = 5) + P(X = 6)\n= C(6,4)(0.6)^4(0.4)^2 + C(6,5)(0.6)^5(0.4)^1 + C(6,6)(0.6)^6(0.4)^0\n≈ 0.54432"}],"shareImage":"share/q379.jpg","shareImageSize":[760,273]},{"id":380,"question":"If 3 of 12 car drivers do not carry driving license,\nwhat is the probability that a traffic inspector who\nrandomly checks 3 car drivers, will catch 1 for not\ncarrying driving license. (use binomial dist.)","page":32,"marks":3,"answer":"Exactly one without a licence ≈ 0.421875","steps":[{"title":"Given and probability formula","formula":"n = 3, p = 0.25, q = 1 − p = 0.75.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 3."},{"title":"Exactly one without a licence","formula":"P(X = 1)\n= C(3,1)(0.25)^1(0.75)^2\n≈ 0.421875"}],"note":"The question requests a binomial model with p = 3/12. Sampling without replacement would give a hypergeometric probability of 108/220.","shareImage":"share/q380.jpg","shareImageSize":[760,266]},{"id":381,"question":"4 coins are tossed simultaneously. What is the\nprobability of getting (i) 2 heads? (ii) at least 2\nheads? (iii) at most 2 heads?","page":32,"marks":3,"answer":"Exactly two heads ≈ 0.375 · At least two heads ≈ 0.6875 · At most two heads ≈ 0.6875","steps":[{"title":"Given and probability formula","formula":"n = 4, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 4."},{"title":"Exactly two heads","formula":"P(X = 2)\n= C(4,2)(0.5)^2(0.5)^2\n≈ 0.375"},{"title":"At least two heads","formula":"P(X = 2) + P(X = 3) + P(X = 4)\n= C(4,2)(0.5)^2(0.5)^2 + C(4,3)(0.5)^3(0.5)^1 + C(4,4)(0.5)^4(0.5)^0\n≈ 0.6875"},{"title":"At most two heads","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= C(4,0)(0.5)^0(0.5)^4 + C(4,1)(0.5)^1(0.5)^3 + C(4,2)(0.5)^2(0.5)^2\n≈ 0.6875"}],"shareImage":"share/q381.jpg","shareImageSize":[760,233]},{"id":382,"question":"A multiple-choice test consists of 8 questions with\n3 answers to each question (of which only one is\ncorrect). A student answers each question by rolling\na balanced die and checking the first answer if he\ngets 1 or 2, the second answer if he gets 3 or 4, and\nthe third answer if he gets 5 or 6. To get a\ndistinction, the student must secure at least 75%\ncorrect answers. If there is no negative marks, what\nis the probability that the student secures a\ndistinction?","page":32,"marks":3,"answer":"At least six correct answers ≈ 0.019661637","steps":[{"title":"Given and probability formula","formula":"n = 8, p = 0.33333333, q = 1 − p = 0.66666667.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 8."},{"title":"At least six correct answers","formula":"P(X = 6) + P(X = 7) + P(X = 8)\n= C(8,6)(0.33333333)^6(0.66666667)^2 + C(8,7)(0.33333333)^7(0.66666667)^1 + C(8,8)(0.33333333)^8(0.66666667)^0\n≈ 0.019661637"}],"shareImage":"share/q382.jpg","shareImageSize":[760,456]},{"id":383,"question":"A man hits a target with probability 1/3 per shot. Find (i) the chance of at least two hits in five shots and (ii) the fewest shots giving more than a 90% chance of at least one hit.","page":32,"marks":3,"answer":"(i) 0.53909465. (ii) 6 shots.","steps":[{"title":"Use the binomial model","formula":"Each shot hits independently with probability 1/3."},{"title":"At least two hits in five shots","formula":"1 − (2/3)⁵ − 5(1/3)(2/3)⁴ = 0.53909465."},{"title":"More than 90% chance of a hit","formula":"Require (2/3)^n < 0.1. Taking logs gives n > ln(0.1)/ln(2/3) ≈ 5.68, so use 6 shots."}],"shareImage":"share/q383.jpg","shareImageSize":[760,309]},{"id":384,"question":"If hens of certain breed lays eggs on 5 days a week\non an average, find how many days during a season\nof 100 days a will poultry keeper with 5 hens of\nthis breed expect to receive at least 4 eggs.","page":32,"marks":3,"answer":"At least four eggs: 55.78033 expected (about 56)","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.71428571, q = 1 − p = 0.28571429.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"At least four eggs","formula":"P(X = 4) + P(X = 5)\n= C(5,4)(0.71428571)^4(0.28571429)^1 + C(5,5)(0.71428571)^5(0.28571429)^0\n≈ 0.5578033\nExpected frequency = N × P(event) = 100 × 0.5578033 ≈ 55.78033."}],"shareImage":"share/q384.jpg","shareImageSize":[760,347]},{"id":385,"question":"An irregular 6 faced die is thrown such that the\nprobability that it gives 3 even numbers in 5 throws\nis twice the probability that it gives 2 even numbers\nin 5 throws. How many sets of exactly 5 trials can\nbe expected to give no even number out of 2500\nsets?","page":33,"marks":3,"answer":"10.288066","steps":[{"title":"Given and formula","formula":"C(5,3)p³(1−p)² = 2C(5,2)p²(1−p)³ for 0 < p < 1."},{"title":"Substitution and result","formula":"Cancel matching factors: p = 2(1−p), so p = 2/3. Expected sets with no even rolls = 2500(1/3)⁵ ≈ 10.29."}],"shareImage":"share/q385.jpg","shareImageSize":[760,329]},{"id":386,"question":"Out of 800 families with 5 children each, how\nmany would you expect to have (i) 3 boys? (ii) 5\ngirls? (iii) either 2 or 3 boys? (iv) at least one boy?\nAssume equal probabilities for boys and girls.","page":33,"marks":4,"answer":"Three boys: 250 expected (about 250) · Five girls: 25 expected (about 25) · Two or three boys: 500 expected (about 500) · At least one boy: 775 expected (about 775)","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"Three boys","formula":"P(X = 3)\n= C(5,3)(0.5)^3(0.5)^2\n≈ 0.3125\nExpected frequency = N × P(event) = 800 × 0.3125 ≈ 250."},{"title":"Five girls","formula":"P(X = 0)\n= C(5,0)(0.5)^0(0.5)^5\n≈ 0.03125\nExpected frequency = N × P(event) = 800 × 0.03125 ≈ 25."},{"title":"Two or three boys","formula":"P(X = 2) + P(X = 3)\n= C(5,2)(0.5)^2(0.5)^3 + C(5,3)(0.5)^3(0.5)^2\n≈ 0.625\nExpected frequency = N × P(event) = 800 × 0.625 ≈ 500."},{"title":"At least one boy","formula":"1 − (P(X = 0))\n= 1 − [C(5,0)(0.5)^0(0.5)^5]\n≈ 0.96875\nExpected frequency = N × P(event) = 800 × 0.96875 ≈ 775."}],"shareImage":"share/q386.jpg","shareImageSize":[760,265]},{"id":387,"question":"Out of 1000 families with 4 children each, how\nmany would you expect to have\n(i) 2 boys and 2 girls? (ii) at least one boy? (iii) no\ngirl? (iv) at most two girls?","page":33,"marks":4,"answer":"Two boys and two girls: 375 expected (about 375) · At least one boy: 937.5 expected (about 938) · No girls: 62.5 expected (about 63) · At most two girls: 687.5 expected (about 688)","steps":[{"title":"Given and probability formula","formula":"n = 4, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 4."},{"title":"Two boys and two girls","formula":"P(X = 2)\n= C(4,2)(0.5)^2(0.5)^2\n≈ 0.375\nExpected frequency = N × P(event) = 1000 × 0.375 ≈ 375."},{"title":"At least one boy","formula":"1 − (P(X = 0))\n= 1 − [C(4,0)(0.5)^0(0.5)^4]\n≈ 0.9375\nExpected frequency = N × P(event) = 1000 × 0.9375 ≈ 937.5."},{"title":"No girls","formula":"P(X = 4)\n= C(4,4)(0.5)^4(0.5)^0\n≈ 0.0625\nExpected frequency = N × P(event) = 1000 × 0.0625 ≈ 62.5."},{"title":"At most two girls","formula":"P(X = 2) + P(X = 3) + P(X = 4)\n= C(4,2)(0.5)^2(0.5)^2 + C(4,3)(0.5)^3(0.5)^1 + C(4,4)(0.5)^4(0.5)^0\n≈ 0.6875\nExpected frequency = N × P(event) = 1000 × 0.6875 ≈ 687.5."}],"shareImage":"share/q387.jpg","shareImageSize":[760,265]},{"id":388,"question":"Fit a binomial distribution to the observed frequencies below.","page":33,"marks":4,"answer":"Binomial fit. Expected frequencies for x = 0 to 5: 1.504592, 9.8912989, 26.010453, 34.198929, 22.482629, 5.9120987.","steps":[{"title":"Find the sample mean","formula":"Σf = 100, Σfx = 284.\nx̄ = Σfx/Σf = 284/100 ≈ 2.84."},{"title":"Estimate the parameter","formula":"p = x̄/n = 2.84/5 = 0.568.\nq = 1 − p = 0.432.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ."},{"title":"Find expected frequencies","formula":"Expected frequency = NP(X = x).\nFor x = 0: 100 × 0.01504592 ≈ 1.504592."}],"table":{"headers":["x","Frequency"],"rows":[[0,2],[1,14],[2,20],[3,34],[4,22],[5,8]]},"workingTable":{"headers":["x","Observed f","fx","P(X = x) or tail","Expected N × P"],"rows":[[0,2,0,"0.01504592","1.504592"],[1,14,14,"0.098912989","9.8912989"],[2,20,40,"0.26010453","26.010453"],[3,34,102,"0.34198929","34.198929"],[4,22,88,"0.22482629","22.482629"],[5,8,40,"0.059120987","5.9120987"]]},"shareImage":"share/q388.jpg","shareImageSize":[760,240]},{"id":389,"question":"Seven unbiased coins are tossed 128 times. Fit a binomial distribution to the observed counts of heads below.","page":33,"marks":3,"answer":"Binomial fit. Expected frequencies for x = 0 to 7: 1.2592757, 8.2437684, 23.128845, 36.050359, 33.714483, 18.917976, 5.8973963, 0.78789651.","steps":[{"title":"Find the sample mean","formula":"Σf = 128, Σfx = 433.\nx̄ = Σfx/Σf = 433/128 ≈ 3.3828125."},{"title":"Estimate the parameter","formula":"p = x̄/n = 3.3828125/7 = 0.48325893.\nq = 1 − p = 0.51674107.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ."},{"title":"Find expected frequencies","formula":"Expected frequency = NP(X = x).\nFor x = 0: 128 × 0.0098380918 ≈ 1.2592757."}],"note":"The table fits p from the observations. If the stated fairness is treated as known, use p = 0.5 instead, with expected frequencies 1, 7, 21, 35, 35, 21, 7, 1.","table":{"headers":["x","Frequency"],"rows":[[0,7],[1,6],[2,19],[3,35],[4,30],[5,23],[6,7],[7,1]]},"workingTable":{"headers":["x","Observed f","fx","P(X = x) or tail","Expected N × P"],"rows":[[0,7,0,"0.0098380918","1.2592757"],[1,6,6,"0.064404441","8.2437684"],[2,19,38,"0.1806941","23.128845"],[3,35,105,"0.28164343","36.050359"],[4,30,120,"0.2633944","33.714483"],[5,23,115,"0.14779668","18.917976"],[6,7,42,"0.046073408","5.8973963"],[7,1,7,"0.0061554415","0.78789651"]]},"shareImage":"share/q389.jpg","shareImageSize":[760,491]},{"id":390,"question":"It is known from past records that 80% of the\nstudents in a school do their homework. Find the\nprobability that during a random check of 10\nstudents (i) all have done their homework (ii) at the\nmost two have not done their homework and (iii) at\nleast one has not done the homework.","page":33,"marks":4,"answer":"Everyone completed homework ≈ 0.10737418 · At most two did not complete it ≈ 0.67779953 · At least one did not complete it ≈ 0.89262582","steps":[{"title":"Given and probability formula","formula":"n = 10, p = 0.2, q = 1 − p = 0.8.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 10."},{"title":"Everyone completed homework","formula":"P(X = 0)\n= C(10,0)(0.2)^0(0.8)^10\n≈ 0.10737418"},{"title":"At most two did not complete it","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= C(10,0)(0.2)^0(0.8)^10 + C(10,1)(0.2)^1(0.8)^9 + C(10,2)(0.2)^2(0.8)^8\n≈ 0.67779953"},{"title":"At least one did not complete it","formula":"1 − (P(X = 0))\n= 1 − [C(10,0)(0.2)^0(0.8)^10]\n≈ 0.89262582"}],"shareImage":"share/q390.jpg","shareImageSize":[760,328]},{"id":391,"question":"Fit a binomial distribution to the observed frequencies below.","page":33,"marks":4,"answer":"Binomial fit. Expected frequencies for x = 0 to 4: 17.41995, 66.748717, 95.911397, 61.251256, 14.66868.","steps":[{"title":"Find the sample mean","formula":"Σf = 256, Σfx = 501.\nx̄ = Σfx/Σf = 501/256 ≈ 1.9570312."},{"title":"Estimate the parameter","formula":"p = x̄/n = 1.9570312/4 = 0.48925781.\nq = 1 − p = 0.51074219.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ."},{"title":"Find expected frequencies","formula":"Expected frequency = NP(X = x).\nFor x = 0: 256 × 0.068046678 ≈ 17.41995."}],"table":{"headers":["x","Frequency"],"rows":[[0,12],[1,66],[2,109],[3,59],[4,10]]},"workingTable":{"headers":["x","Observed f","fx","P(X = x) or tail","Expected N × P"],"rows":[[0,12,0,"0.068046678","17.41995"],[1,66,66,"0.26073718","66.748717"],[2,109,218,"0.3746539","95.911397"],[3,59,177,"0.23926272","61.251256"],[4,10,40,"0.057299532","14.66868"]]},"shareImage":"share/q391.jpg","shareImageSize":[760,255]},{"id":392,"question":"The sum and product of the mean and variance of a binomial distribution are 25/3 and 50/3. Determine the distribution.","page":33,"marks":3,"answer":"X ~ Bin(15, 1/3)","steps":[{"title":"Given and formula","formula":"Use t² − (25/3)t + 50/3 = 0 for the mean and variance. The larger root is the mean."},{"title":"Substitution and result","formula":"Roots (25 ± 5)/6 are 5 and 10/3. Then q = (10/3)/5 = 2/3, p = 1/3 and n = 15."}],"shareImage":"share/q392.jpg","shareImageSize":[760,246]},{"id":393,"question":"The mean and variance of a binomial distribution\nare 3 and 1.2 respectively. Find 𝑛,𝑝 and 𝑃(𝑋 < 4).","page":33,"marks":2,"answer":"P(X < 4) ≈ 0.66304","steps":[{"title":"Given and parameter calculation","formula":"Mean: np = 3   (1)\nVariance: npq = 1.2   (2)\nDivide (2) by (1): q = 1.2/3 = 0.4.\n∴ p = 0.6 and n = 3/0.6 = 5."},{"title":"Probability formula","formula":"n = 5, p = 0.6, q = 1 − p = 0.4.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"P(X < 4)","formula":"1 − (P(X = 4) + P(X = 5))\n= 1 − [C(5,4)(0.6)^4(0.4)^1 + C(5,5)(0.6)^5(0.4)^0]\n≈ 0.66304"}],"shareImage":"share/q393.jpg","shareImageSize":[760,202]},{"id":394,"question":"If a publisher of nontechnical books takes great\npains to ensure that its books are free of\ntypographical errors, so that the probability of any\ngiven page containing at least one such error is\n0.005 and errors are independent from page to\npage, what is the probability that one of its 400-\npage novels will contain (i) exactly one page with\nerrors? (ii) At most three pages with errors?","page":33,"marks":3,"answer":"Exactly one page with errors ≈ 0.27066943 · At most three pages with errors ≈ 0.85757665","steps":[{"title":"Given and probability formula","formula":"n = 400, p = 0.005, q = 1 − p = 0.995.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 400."},{"title":"Exactly one page with errors","formula":"P(X = 1)\n= C(400,1)(0.005)^1(0.995)^399\n≈ 0.27066943"},{"title":"At most three pages with errors","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3)\n= C(400,0)(0.005)^0(0.995)^400 + C(400,1)(0.005)^1(0.995)^399 + C(400,2)(0.005)^2(0.995)^398 + C(400,3)(0.005)^3(0.995)^397\n≈ 0.85757665"}],"shareImage":"share/q394.jpg","shareImageSize":[760,393]},{"id":395,"question":"Assume that on the average one telephone number\nout of fifteen called between 1 p.m. and 2 p.m. on\nweek days is busy. What is the probability that if 6\nrandomly selected telephone numbers are called (i)\nnot more than three, (ii) at least three of them\nwould be busy?","page":33,"marks":3,"answer":"Not more than three busy ≈ 0.99973443 · At least three busy ≈ 0.0050835665","steps":[{"title":"Given and probability formula","formula":"n = 6, p = 0.066666667, q = 1 − p = 0.93333333.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 6."},{"title":"Not more than three busy","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3)\n= C(6,0)(0.066666667)^0(0.93333333)^6 + C(6,1)(0.066666667)^1(0.93333333)^5 + C(6,2)(0.066666667)^2(0.93333333)^4 + C(6,3)(0.066666667)^3(0.93333333)^3\n≈ 0.99973443"},{"title":"At least three busy","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2))\n= 1 − [C(6,0)(0.066666667)^0(0.93333333)^6 + C(6,1)(0.066666667)^1(0.93333333)^5 + C(6,2)(0.066666667)^2(0.93333333)^4]\n≈ 0.0050835665"}],"shareImage":"share/q395.jpg","shareImageSize":[760,409]},{"id":396,"question":"In eight throws of a die, 5 or 6 is considered as a\nsuccess. Find the mean number of success and the\nstandard deviation.","page":34,"marks":2,"answer":"Mean = 8/3. SD = 4/3.","steps":[{"title":"Given and formula","formula":"A 5 or 6 occurs with probability 2/6 = 1/3, so X ~ Bin(8,1/3)."},{"title":"Substitution and result","formula":"E[X] = 8/3. Var(X) = 8(1/3)(2/3) = 16/9, so SD = 4/3."}],"shareImage":"share/q396.jpg","shareImageSize":[760,234]},{"id":397,"question":"If 10% of the screws produced by a machine are\ndefective, find the probability that out of 5 screws\nchosen at random, (i) none is defective, (ii) one is\ndefective, and (iii) at most two are defective.","page":34,"marks":3,"answer":"None defective ≈ 0.59049 · One defective ≈ 0.32805 · At most two defective ≈ 0.99144","steps":[{"title":"Given and probability formula","formula":"n = 5, p = 0.1, q = 1 − p = 0.9.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 5."},{"title":"None defective","formula":"P(X = 0)\n= C(5,0)(0.1)^0(0.9)^5\n≈ 0.59049"},{"title":"One defective","formula":"P(X = 1)\n= C(5,1)(0.1)^1(0.9)^4\n≈ 0.32805"},{"title":"At most two defective","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= C(5,0)(0.1)^0(0.9)^5 + C(5,1)(0.1)^1(0.9)^4 + C(5,2)(0.1)^2(0.9)^3\n≈ 0.99144"}],"shareImage":"share/q397.jpg","shareImageSize":[760,266]},{"id":398,"question":"In sampling a large number of parts manufactured by\na machine, the mean number of defectives in a\nsample of 20 is 2. Out of 1000 such samples, how\nmany would be expected to contain exactly two\ndefective parts?","page":34,"marks":3,"answer":"Exactly two defective parts: 285.17981 expected (about 285)","steps":[{"title":"Given and probability formula","formula":"n = 20, p = 0.1, q = 1 − p = 0.9.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 20."},{"title":"Exactly two defective parts","formula":"P(X = 2)\n= C(20,2)(0.1)^2(0.9)^18\n≈ 0.28517981\nExpected frequency = N × P(event) = 1000 × 0.28517981 ≈ 285.17981."}],"note":"The mean number of defectives is 20p = 2.","shareImage":"share/q398.jpg","shareImageSize":[760,297]},{"id":399,"question":"A multiple-choice test in mathematics with 40\nquestions, each having 5 options, is given to a\nstudent. If the student guesses all questions, what are\nthe mean and standard deviation of the number of\ncorrect answers? (Use Binomial Distribution)","page":34,"marks":3,"answer":"Mean = 8. SD ≈ 2.5298.","steps":[{"title":"Given and formula","formula":"A random guess has probability 1/5 of being correct."},{"title":"Substitution and result","formula":"E[X] = 40/5 = 8. SD(X) = √[40(1/5)(4/5)] = √6.4."}],"shareImage":"share/q399.jpg","shareImageSize":[760,298]},{"id":400,"question":"Suppose that a central university has to form a\ncommittee of 5 members from a list of 20\ncandidates out of whom 12 are teachers and 8 are\nstudents. If the members of the committee are\nselected at random. What is the probability that the\nmajority of the committee members are students?","page":34,"marks":3,"answer":"0.29618163","steps":[{"title":"Given and formula","formula":"Choose 5 people without replacement. A majority means 3, 4 or 5 students."},{"title":"Substitution and result","formula":"Divide C(8,3)C(12,2) + C(8,4)C(12,1) + C(8,5) by C(20,5)."}],"shareImage":"share/q400.jpg","shareImageSize":[760,330]},{"id":401,"question":"In a binomial distribution consisting of 5 inependent\ntrials, the probability of 1 and 2 successes are\n0.4096 and 0.2048 respectively. Find the parameter\n𝑝 of the distribution.","page":34,"marks":3,"answer":"0.2","steps":[{"title":"Given and formula","formula":"For n = 5, the ratio P(X = 2)/P(X = 1) is 2p/(1−p)."},{"title":"Substitution and result","formula":"0.2048/0.4096 = 0.5, so 2p = 0.5(1−p) and p = 0.2."}],"shareImage":"share/q401.jpg","shareImageSize":[760,267]},{"id":402,"question":"Half the population is vegetarian. If 100 investigators each sample 10 people, how many are expected to report three or fewer vegetarians?","page":34,"marks":3,"answer":"At most three vegetarians: 17.1875 expected (about 17)","steps":[{"title":"Given and probability formula","formula":"n = 10, p = 0.5, q = 1 − p = 0.5.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 10."},{"title":"At most three vegetarians","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3)\n= C(10,0)(0.5)^0(0.5)^10 + C(10,1)(0.5)^1(0.5)^9 + C(10,2)(0.5)^2(0.5)^8 + C(10,3)(0.5)^3(0.5)^7\n≈ 0.171875\nExpected frequency = N × P(event) = 100 × 0.171875 ≈ 17.1875."}],"shareImage":"share/q402.jpg","shareImageSize":[760,374]},{"id":403,"question":"If 10% of toys produced by a machine are\ndefective. Determine the probability that out of 10\ntoys, chosen at random (I) 1 (II) none (III) at most 2\ntoys will be defective.","page":34,"marks":4,"answer":"One defective ≈ 0.38742049 · None defective ≈ 0.34867844 · At most two defective ≈ 0.92980917","steps":[{"title":"Given and probability formula","formula":"n = 10, p = 0.1, q = 1 − p = 0.9.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 10."},{"title":"One defective","formula":"P(X = 1)\n= C(10,1)(0.1)^1(0.9)^9\n≈ 0.38742049"},{"title":"None defective","formula":"P(X = 0)\n= C(10,0)(0.1)^0(0.9)^10\n≈ 0.34867844"},{"title":"At most two defective","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= C(10,0)(0.1)^0(0.9)^10 + C(10,1)(0.1)^1(0.9)^9 + C(10,2)(0.1)^2(0.9)^8\n≈ 0.92980917"}],"shareImage":"share/q403.jpg","shareImageSize":[760,265]},{"id":404,"question":"A book contains 100 misprints distributed randomly\nthroughout its 100 pages. What is the probability\nthat a page observed at random contains at least two\nmisprints? Assume Poisson Distribution.","page":34,"marks":3,"answer":"At least two misprints ≈ 0.26424112","steps":[{"title":"Given and probability formula","formula":"λ = 1.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At least two misprints","formula":"1 − (P(X = 0) + P(X = 1))\n= 1 − [e^(−1)(1)^0/0! + e^(−1)(1)^1/1!]\n≈ 0.26424112"}],"shareImage":"share/q404.jpg","shareImageSize":[760,265]},{"id":405,"question":"Suppose a random book of 1045 pages contains 35\nprinting errors. If these errors are distributed as\nPoisson throughout the book, what is the\nprobability that 60 pages, selected at random, (1)\nwill be free from errors and (2) will have 2 errors?","page":34,"marks":4,"answer":"No printing errors ≈ 0.13404639 · Exactly two printing errors ≈ 0.27066439","steps":[{"title":"Given and probability formula","formula":"λ = 2.0095694.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No printing errors","formula":"P(X = 0)\n= e^(−2.0095694)(2.0095694)^0/0!\n≈ 0.13404639"},{"title":"Exactly two printing errors","formula":"P(X = 2)\n= e^(−2.0095694)(2.0095694)^2/2!\n≈ 0.27066439"}],"shareImage":"share/q405.jpg","shareImageSize":[760,297]},{"id":406,"question":"If 2% of light bulbs are defective, find the\nprobability that\n(1) at least one is defective, and\n(2) exactly 7 are defective.\nAlso, find P (1 < X < 8) in a sample of 100.\nAssume Poisson Distribution.","page":34,"marks":3,"answer":"At least one defective ≈ 0.86466472 · Exactly seven defective ≈ 0.0034370866 · P(1 < X < 8) ≈ 0.59289743","steps":[{"title":"Given and probability formula","formula":"λ = 2.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At least one defective","formula":"1 − (P(X = 0))\n= 1 − [e^(−2)(2)^0/0!]\n≈ 0.86466472"},{"title":"Exactly seven defective","formula":"P(X = 7)\n= e^(−2)(2)^7/7!\n≈ 0.0034370866"},{"title":"P(1 < X < 8)","formula":"P(2 ≤ X ≤ 7)\n= Σ e^(−2)(2)^x/x!, x = 2, …, 7\n≈ 0.59289743"}],"shareImage":"share/q406.jpg","shareImageSize":[760,328]},{"id":407,"question":"A car hire firm has two cars which it hires out day to\nday. The number of demands for a car on each day is\ndistributed as Poisson variate with mean 1.5.\nCalculate the proportion of days on which (i) neither\ncar is used, and (ii) some demand is refused.\n(𝑒−1.5 = 0.2231).","page":34,"marks":3,"answer":"Neither car used ≈ 0.22313016 · Some demand refused ≈ 0.19115317","steps":[{"title":"Given and probability formula","formula":"λ = 1.5.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Neither car used","formula":"P(X = 0)\n= e^(−1.5)(1.5)^0/0!\n≈ 0.22313016"},{"title":"Some demand refused","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2))\n= 1 − [e^(−1.5)(1.5)^0/0! + e^(−1.5)(1.5)^1/1! + e^(−1.5)(1.5)^2/2!]\n≈ 0.19115317"}],"shareImage":"share/q407.jpg","shareImageSize":[760,330]},{"id":408,"question":"The number of flaws in a fiber optic cable follows a\nPoisson process with an average of 0.6 per 100 feet.\n(i) Find the probability of exactly 2 flaws in a 200-\nfoot cable. (ii) Find the probability of exactly 1\nflaw in the first 100 feet and exactly 1 flaw in the\nsecond 100 feet.","page":34,"marks":3,"answer":"(i) 0.21685983. (ii) 0.10842992.","steps":[{"title":"Given and formula","formula":"Use λ = 1.2 for the whole cable and λ = 0.6 per half."},{"title":"Substitution and result","formula":"(i) e^(−1.2) × 1.2²/2!. (ii) Independent halves give [e^(−0.6) × 0.6]²."}],"shareImage":"share/q408.jpg","shareImageSize":[760,355]},{"id":409,"question":"Potholes on a highway can be a serious problem.\nThe past experience suggests that there are, on the\naverage, 2 potholes per mile after a certain amount\nof usage. It is assumed that the Poisson process\napplies to the random variable “number of potholes.”\nWhat is the probability that no more than 4 potholes\nwill occur in a given section of 5 miles?","page":35,"marks":3,"answer":"At most four potholes ≈ 0.029252688","steps":[{"title":"Given and probability formula","formula":"λ = 10.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At most four potholes","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3) + P(X = 4)\n= e^(−10)(10)^0/0! + e^(−10)(10)^1/1! + e^(−10)(10)^2/2! + e^(−10)(10)^3/3! + e^(−10)(10)^4/4!\n≈ 0.029252688"}],"shareImage":"share/q409.jpg","shareImageSize":[760,360]},{"id":410,"question":"If the mean of a Poisson variable is 1.8, find\n(i) 𝑃(𝑋 > 1) (ii) 𝑃(𝑋 = 5) (iii) 𝑃(0 < 𝑋 < 5).","page":35,"marks":3,"answer":"P(X > 1) ≈ 0.53716311 · P(X = 5) ≈ 0.026028624 · P(0 < X < 5) ≈ 0.79829445","steps":[{"title":"Given and probability formula","formula":"λ = 1.8.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X > 1)","formula":"1 − (P(X = 0) + P(X = 1))\n= 1 − [e^(−1.8)(1.8)^0/0! + e^(−1.8)(1.8)^1/1!]\n≈ 0.53716311"},{"title":"P(X = 5)","formula":"P(X = 5)\n= e^(−1.8)(1.8)^5/5!\n≈ 0.026028624"},{"title":"P(0 < X < 5)","formula":"P(X = 1) + P(X = 2) + P(X = 3) + P(X = 4)\n= e^(−1.8)(1.8)^1/1! + e^(−1.8)(1.8)^2/2! + e^(−1.8)(1.8)^3/3! + e^(−1.8)(1.8)^4/4!\n≈ 0.79829445"}],"shareImage":"share/q410.jpg","shareImageSize":[760,202]},{"id":411,"question":"If 3P(X = 4) = (1/2)P(X = 2) + P(X = 0) for a Poisson variable, find its mean and P(X ≤ 2).","page":35,"marks":3,"answer":"P(X ≤ 2) ≈ 0.67667642","steps":[{"title":"Given and parameter calculation","formula":"Substitute P(X = x) = e^(−λ)λˣ/x! in the given equation.\n3e^(−λ)λ⁴/4! = (1/2)e^(−λ)λ²/2! + e^(−λ).\nCancel e^(−λ): λ⁴/8 = λ²/4 + 1.\n∴ λ⁴ − 2λ² − 8 = (λ² − 4)(λ² + 2) = 0.\nSince λ > 0, λ = 2. Thus the mean is 2."},{"title":"Probability formula","formula":"λ = 2.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X ≤ 2)","formula":"P(X = 0) + P(X = 1) + P(X = 2)\n= e^(−2)(2)^0/0! + e^(−2)(2)^1/1! + e^(−2)(2)^2/2!\n≈ 0.67667642"}],"shareImage":"share/q411.jpg","shareImageSize":[760,248]},{"id":412,"question":"An insurance company insured 4000 people against\nloss of both eyes in a car accident. Based on\nprevious data, the rates were computed on the\nassumption that on the average, 10 persons in\n100000 will have car accidents each year that result\nin this type of injury. What is the probability that\nmore than 3 of the insured will collect on their\npolicy in a given year?","page":35,"marks":3,"answer":"More than three claims ≈ 0.00077625138","steps":[{"title":"Given and probability formula","formula":"λ = 0.4.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"More than three claims","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3))\n= 1 − [e^(−0.4)(0.4)^0/0! + e^(−0.4)(0.4)^1/1! + e^(−0.4)(0.4)^2/2! + e^(−0.4)(0.4)^3/3!]\n≈ 0.00077625138"}],"shareImage":"share/q412.jpg","shareImageSize":[760,391]},{"id":413,"question":"Assume that the probability of an individual coal\nminer being killed in a mine accident during a year\nis 1/2400. Use the Poisson distribution to calculate\nthe probability that in a mine employing 200\nminers, there will be at least one fatal accident in a\nyear.","page":35,"marks":4,"answer":"At least one fatal accident ≈ 0.079955585","steps":[{"title":"Given and probability formula","formula":"λ = 0.083333333.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"At least one fatal accident","formula":"1 − (P(X = 0))\n= 1 − [e^(−0.083333333)(0.083333333)^0/0!]\n≈ 0.079955585"}],"shareImage":"share/q413.jpg","shareImageSize":[760,329]},{"id":414,"question":"Suppose a book of 585 pages contains 43\ntypographical errors. If these errors are randomly\ndistributed throughout the book, what is the\nprobability that 10 pages, selected at random, will\nbe free from errors?","page":35,"marks":3,"answer":"No typographical errors ≈ 0.47948497","steps":[{"title":"Given and probability formula","formula":"λ = 0.73504274.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No typographical errors","formula":"P(X = 0)\n= e^(−0.73504274)(0.73504274)^0/0!\n≈ 0.47948497"}],"shareImage":"share/q414.jpg","shareImageSize":[760,297]},{"id":415,"question":"The number of accidents in a year attributed to taxi\ndrivers in a city follows Poisson distribution with a\nmean of 3. Out of 1000 taxi drivers, find\napproximately the number of drivers with (i) no\naccidents in a year (ii) more than 3 accidents in a\nyear.","page":35,"marks":3,"answer":"No accidents: 49.787068 expected (about 50) · More than three accidents: 352.76811 expected (about 353)","steps":[{"title":"Given and probability formula","formula":"λ = 3.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No accidents","formula":"P(X = 0)\n= e^(−3)(3)^0/0!\n≈ 0.049787068\nExpected frequency = N × P(event) = 1000 × 0.049787068 ≈ 49.787068."},{"title":"More than three accidents","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3))\n= 1 − [e^(−3)(3)^0/0! + e^(−3)(3)^1/1! + e^(−3)(3)^2/2! + e^(−3)(3)^3/3!]\n≈ 0.35276811\nExpected frequency = N × P(event) = 1000 × 0.35276811 ≈ 352.76811."}],"shareImage":"share/q415.jpg","shareImageSize":[760,328]},{"id":416,"question":"Mistakes per page follow a Poisson distribution. Find fitted expected frequencies for the observed data below.","page":35,"marks":4,"answer":"Poisson fit. Expected frequencies for x = 0 to 5: 26.775619, 40.163429, 30.122572, 15.061286, 5.6479822, 1.6943947.","steps":[{"title":"Find the sample mean","formula":"Σf = 120, Σfx = 180.\nx̄ = Σfx/Σf = 180/120 ≈ 1.5."},{"title":"Estimate the parameter","formula":"λ = x̄ = 1.5.\nP(X = x) = e^(−λ)λˣ/x!."},{"title":"Find expected frequencies","formula":"Expected frequency = NP(X = x).\nFor x = 0: 120 × 0.22313016 ≈ 26.775619."}],"table":{"headers":["x","Frequency"],"rows":[[0,40],[1,30],[2,20],[3,15],[4,10],[5,5]]},"workingTable":{"headers":["x","Observed f","fx","P(X = x) or tail","Expected N × P"],"rows":[[0,40,0,"0.22313016","26.775619"],[1,30,30,"0.33469524","40.163429"],[2,20,40,"0.25102143","30.122572"],[3,15,45,"0.12551072","15.061286"],[4,10,40,"0.047066518","5.6479822"],[5,5,25,"0.014119955","1.6943947"],["6 and above",0,0,"0.0044559808","0.53471769"]]},"shareImage":"share/q416.jpg","shareImageSize":[760,482]},{"id":417,"question":"A manufacturer of electric bulbs sends out 500 lots\neach consisting of 100 bulbs. If 5 % bulbs are\ndefective, in how many lots can we expect (i) 97 or\nmore good bulbs? (ii) less than 96 good bulbs?","page":35,"marks":3,"answer":"At least 97 good bulbs (at most 3 defective): 128.91933 expected (about 129) · Fewer than 96 good bulbs (at least 5 defective): 282.00935 expected (about 282)","steps":[{"title":"Given and probability formula","formula":"n = 100, p = 0.05, q = 1 − p = 0.95.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 100."},{"title":"At least 97 good bulbs (at most 3 defective)","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3)\n= C(100,0)(0.05)^0(0.95)^100 + C(100,1)(0.05)^1(0.95)^99 + C(100,2)(0.05)^2(0.95)^98 + C(100,3)(0.05)^3(0.95)^97\n≈ 0.25783866\nExpected frequency = N × P(event) = 500 × 0.25783866 ≈ 128.91933."},{"title":"Fewer than 96 good bulbs (at least 5 defective)","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3) + P(X = 4))\n= 1 − [C(100,0)(0.05)^0(0.95)^100 + C(100,1)(0.05)^1(0.95)^99 + C(100,2)(0.05)^2(0.95)^98 + C(100,3)(0.05)^3(0.95)^97 + C(100,4)(0.05)^4(0.95)^96]\n≈ 0.5640187\nExpected frequency = N × P(event) = 500 × 0.5640187 ≈ 282.00935."}],"shareImage":"share/q417.jpg","shareImageSize":[760,265]},{"id":418,"question":"The probability of a defective article is 1/500. In 20,000 packets of 20 articles each, estimate the number with zero, one and two defectives.","page":35,"marks":4,"answer":"No defectives: 19215.789 expected (about 19216) · One defective: 768.63155 expected (about 769) · Two defectives: 15.372631 expected (about 15)","steps":[{"title":"Given and probability formula","formula":"λ = 0.04.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No defectives","formula":"P(X = 0)\n= e^(−0.04)(0.04)^0/0!\n≈ 0.96078944\nExpected frequency = N × P(event) = 20000 × 0.96078944 ≈ 19215.789."},{"title":"One defective","formula":"P(X = 1)\n= e^(−0.04)(0.04)^1/1!\n≈ 0.038431578\nExpected frequency = N × P(event) = 20000 × 0.038431578 ≈ 768.63155."},{"title":"Two defectives","formula":"P(X = 2)\n= e^(−0.04)(0.04)^2/2!\n≈ 0.00076863155\nExpected frequency = N × P(event) = 20000 × 0.00076863155 ≈ 15.372631."}],"shareImage":"share/q418.jpg","shareImageSize":[760,401]},{"id":419,"question":"Fit a Poisson distribution to the observed frequencies below.","page":36,"marks":4,"answer":"Poisson fit. Expected frequencies for x = 0 to 8: 69.589111, 137.22973, 135.30851, 88.942794, 43.848797, 17.293966, 5.6839501, 1.6012499, 0.39470811.","steps":[{"title":"Find the sample mean","formula":"Σf = 500, Σfx = 986.\nx̄ = Σfx/Σf = 986/500 ≈ 1.972."},{"title":"Estimate the parameter","formula":"λ = x̄ = 1.972.\nP(X = x) = e^(−λ)λˣ/x!."},{"title":"Find expected frequencies","formula":"Expected frequency = NP(X = x).\nFor x = 0: 500 × 0.13917822 ≈ 69.589111."}],"table":{"headers":["x","Frequency"],"rows":[[0,56],[1,156],[2,132],[3,92],[4,37],[5,22],[6,4],[7,0],[8,1]]},"workingTable":{"headers":["x","Observed f","fx","P(X = x) or tail","Expected N × P"],"rows":[[0,56,0,"0.13917822","69.589111"],[1,156,156,"0.27445945","137.22973"],[2,132,264,"0.27061702","135.30851"],[3,92,276,"0.17788559","88.942794"],[4,37,148,"0.087697595","43.848797"],[5,22,110,"0.034587931","17.293966"],[6,4,24,"0.0113679","5.6839501"],[7,0,0,"0.0032024999","1.6012499"],[8,1,8,"0.00078941622","0.39470811"],["9 and above",0,0,"0.00021437646","0.10718823"]]},"shareImage":"share/q419.jpg","shareImageSize":[760,305]},{"id":420,"question":"If 𝑋 is a Poisson variate such that\n𝑃(𝑋 = 0) = 𝑃(𝑋 = 1), find 𝑃(𝑋 = 0) and using\nrecurrence relation formula, find the probabilities at\n𝑥 = 1,2,3,4 and 5.","page":36,"marks":3,"answer":"P(X = 0) ≈ 0.36787944 · P(X = 1) ≈ 0.36787944 · P(X = 2) ≈ 0.18393972 · P(X = 3) ≈ 0.06131324 · P(X = 4) ≈ 0.01532831 · P(X = 5) ≈ 0.003065662","steps":[{"title":"Given and probability formula","formula":"λ = 1.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X = 0)","formula":"P(X = 0)\n= e^(−1)(1)^0/0!\n≈ 0.36787944"},{"title":"P(X = 1)","formula":"P(X = 1)\n= e^(−1)(1)^1/1!\n≈ 0.36787944"},{"title":"P(X = 2)","formula":"P(X = 2)\n= e^(−1)(1)^2/2!\n≈ 0.18393972"},{"title":"P(X = 3)","formula":"P(X = 3)\n= e^(−1)(1)^3/3!\n≈ 0.06131324"},{"title":"P(X = 4)","formula":"P(X = 4)\n= e^(−1)(1)^4/4!\n≈ 0.01532831"},{"title":"P(X = 5)","formula":"P(X = 5)\n= e^(−1)(1)^5/5!\n≈ 0.003065662"}],"note":"The equation P(1) = P(0) gives λ = 1. Start with P(0) = e⁻¹ and use P(k) = P(k−1)/k.","shareImage":"share/q420.jpg","shareImageSize":[760,267]},{"id":421,"question":"If two cards are drawn from a pack of 52 cards\nwhich are diamonds, using Poisson distribution, find\nthe probability of getting two diamonds at least 3\ntimes in 51 consecutive trials of two cards drawing\neach time.","page":36,"marks":3,"answer":"Two diamonds at least three times ≈ 0.57680992","steps":[{"title":"Given and probability formula","formula":"λ = 3.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Two diamonds at least three times","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2))\n= 1 − [e^(−3)(3)^0/0! + e^(−3)(3)^1/1! + e^(−3)(3)^2/2!]\n≈ 0.57680992"}],"note":"Each draw of two cards has probability (13/52)(12/51) = 1/17 of two diamonds. Assume the deck is reset between trials, giving Poisson rate 51/17 = 3.","shareImage":"share/q421.jpg","shareImageSize":[760,298]},{"id":422,"question":"A manufacturer of blades knows that 5% of his\nproduct is defective. If he sells blades in boxes of\n100, and guarantees that not more than 10 blades\nwill be defective, what is the probability that a box\nwill fail to meet the guaranteed quality?","page":36,"marks":3,"answer":"More than ten defective blades ≈ 0.01147241","steps":[{"title":"Given and probability formula","formula":"n = 100, p = 0.05, q = 1 − p = 0.95.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 100."},{"title":"More than ten defective blades","formula":"1 − (P(0 ≤ X ≤ 10))\n= 1 − [Σ C(100,x)(0.05)^x(0.95)^(100−x), x = 0, …, 10]\n≈ 0.01147241"}],"shareImage":"share/q422.jpg","shareImageSize":[760,298]},{"id":423,"question":"Air Corporation having had just 2 air crashes during\nits first fifty years of existence wants to make the\nnext decade “air crash-free”. Assuming that the same\ntrend will continue, what is the probability of the\ncorporation meeting the target?","page":36,"marks":3,"answer":"No crashes in ten years ≈ 0.67032005","steps":[{"title":"Given and probability formula","formula":"λ = 0.4.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No crashes in ten years","formula":"P(X = 0)\n= e^(−0.4)(0.4)^0/0!\n≈ 0.67032005"}],"shareImage":"share/q423.jpg","shareImageSize":[760,298]},{"id":424,"question":"If a random variable has a Poisson distribution such\nthat 𝑃(𝑋 = 1) = 𝑃(𝑋 = 2), find (i) the mean of the\ndistribution, (ii) 𝑃(𝑋 = 4), (iii) 𝑃(𝑋 ≥ 1), and (iv)\n𝑃(1 < 𝑋 < 4).","page":36,"marks":4,"answer":"P(X = 4) ≈ 0.090223522 · P(X ≥ 1) ≈ 0.86466472 · P(1 < X < 4) ≈ 0.45111761","steps":[{"title":"Given and parameter calculation","formula":"Given P(X = 2) = P(X = 1).\ne^(−λ)λ²/2! = e^(−λ)λ.\n∴ λ/2 = 1 for λ > 0, so the mean is λ = 2."},{"title":"Probability formula","formula":"λ = 2.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X = 4)","formula":"P(X = 4)\n= e^(−2)(2)^4/4!\n≈ 0.090223522"},{"title":"P(X ≥ 1)","formula":"1 − (P(X = 0))\n= 1 − [e^(−2)(2)^0/0!]\n≈ 0.86466472"},{"title":"P(1 < X < 4)","formula":"P(X = 2) + P(X = 3)\n= e^(−2)(2)^2/2! + e^(−2)(2)^3/3!\n≈ 0.45111761"}],"shareImage":"share/q424.jpg","shareImageSize":[760,266]},{"id":425,"question":"If 𝑋 is a Poisson variate such that 𝑃(𝑋 = 2) =\n9𝑃(𝑋 = 4) + 90 𝑃(𝑋 = 6). Find (i) the means of\n𝑋, (ii) the variance of 𝑋, (iii) 𝑃(𝑋 < 2), (iv)\n𝑃(𝑋 > 4), and (v) 𝑃(𝑋 ≥ 1).","page":36,"marks":5,"answer":"P(X < 2) ≈ 0.73575888 · P(X > 4) ≈ 0.0036598468 · P(X ≥ 1) ≈ 0.63212056","steps":[{"title":"Given and probability formula","formula":"λ = 1.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"P(X < 2)","formula":"P(X = 0) + P(X = 1)\n= e^(−1)(1)^0/0! + e^(−1)(1)^1/1!\n≈ 0.73575888"},{"title":"P(X > 4)","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3) + P(X = 4))\n= 1 − [e^(−1)(1)^0/0! + e^(−1)(1)^1/1! + e^(−1)(1)^2/2! + e^(−1)(1)^3/3! + e^(−1)(1)^4/4!]\n≈ 0.0036598468"},{"title":"P(X ≥ 1)","formula":"1 − (P(X = 0))\n= 1 − [e^(−1)(1)^0/0!]\n≈ 0.63212056"}],"note":"For λ > 0, cancel e^(−λ)λ² and multiply by 8: 4 = 3λ² + λ⁴. Hence λ² = 1 and both mean and variance equal 1.","shareImage":"share/q425.jpg","shareImageSize":[760,268]},{"id":426,"question":"If the probability that an individual suffers a bad\nreaction from a particular injection is 0.001,\ndetermine the probability that out of 2000\nindividuals (i) exactly three, and (ii) more than two\nindividuals suffer a bad reaction.","page":36,"marks":3,"answer":"Exactly three reactions ≈ 0.18053733 · More than two reactions ≈ 0.32332356","steps":[{"title":"Given and probability formula","formula":"n = 2000, p = 0.001, q = 1 − p = 0.999.\nP(X = x) = ⁿCₓ pˣ qⁿ⁻ˣ, for x = 0, 1, …, 2000."},{"title":"Exactly three reactions","formula":"P(X = 3)\n= C(2000,3)(0.001)^3(0.999)^1997\n≈ 0.18053733"},{"title":"More than two reactions","formula":"1 − (P(X = 0) + P(X = 1) + P(X = 2))\n= 1 − [C(2000,0)(0.001)^0(0.999)^2000 + C(2000,1)(0.001)^1(0.999)^1999 + C(2000,2)(0.001)^2(0.999)^1998]\n≈ 0.32332356"}],"shareImage":"share/q426.jpg","shareImageSize":[760,298]},{"id":427,"question":"It is known from past experience that in a certain\nplant, there are on the average 4 industrial\naccidents per year. Find the probability that in a\ngiven year, there will be less than 4 accidents.\nAssume Poison distribution.","page":36,"marks":3,"answer":"Fewer than four accidents ≈ 0.43347012","steps":[{"title":"Given and probability formula","formula":"λ = 4.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Fewer than four accidents","formula":"P(X = 0) + P(X = 1) + P(X = 2) + P(X = 3)\n= e^(−4)(4)^0/0! + e^(−4)(4)^1/1! + e^(−4)(4)^2/2! + e^(−4)(4)^3/3!\n≈ 0.43347012"}],"shareImage":"share/q427.jpg","shareImageSize":[760,298]},{"id":428,"question":"Suppose that a local appliances shop has found\nfrom experience that the demand for tub lights is\nroughly distributed as Poisson with a mean of 4\ntube lights per week. If the shop keeps 6 tube lights\nduring a particular week, what is the probability\nthat the demand will exceed the supply during that\nweek?","page":36,"marks":3,"answer":"Demand exceeds six lights ≈ 0.11067398","steps":[{"title":"Given and probability formula","formula":"λ = 4.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"Demand exceeds six lights","formula":"1 − (P(0 ≤ X ≤ 6))\n= 1 − [Σ e^(−4)(4)^x/x!, x = 0, …, 6]\n≈ 0.11067398"}],"shareImage":"share/q428.jpg","shareImageSize":[760,361]},{"id":429,"question":"A manufacturer, who produce medicine bottles,\nfind that 0.1% of the bottles are defective. The\nbottles are packed in boxes containing 500 bottles.\nA drug manufacturer buys 100 boxes from the\nproducer of bottles. Using Poisson distribution, find\nhow many boxes will contain\n(i) No defective bottles and (ii) at least 2 defective\nbottles.","page":36,"marks":4,"answer":"No defective bottles: 60.653066 expected (about 61) · At least two defective bottles: 9.020401 expected (about 9)","steps":[{"title":"Given and probability formula","formula":"λ = 0.5.\nP(X = x) = e^(−λ) λˣ/x!, for x = 0, 1, 2, … ."},{"title":"No defective bottles","formula":"P(X = 0)\n= e^(−0.5)(0.5)^0/0!\n≈ 0.60653066\nExpected frequency = N × P(event) = 100 × 0.60653066 ≈ 60.653066."},{"title":"At least two defective bottles","formula":"1 − (P(X = 0) + P(X = 1))\n= 1 − [e^(−0.5)(0.5)^0/0! + e^(−0.5)(0.5)^1/1!]\n≈ 0.09020401\nExpected frequency = N × P(event) = 100 × 0.09020401 ≈ 9.020401."}],"shareImage":"share/q429.jpg","shareImageSize":[760,466]}]};
